// Canvas Avoider game
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width = canvas.clientWidth;
  const h = canvas.height = canvas.clientHeight;

  // player
  const player = {x: w/2, y: h/2, r: 10, speed: 200}; // px/s
  const keys = {};
  window.addEventListener('keydown', e => keys[e.key] = true);
  window.addEventListener('keyup', e => keys[e.key] = false);

  // obstacles
  const obstacles = [];
  const spawnInterval = 800; // ms
  let lastSpawn = 0;

  // timing
  let startTime = null;
  let gameOver = false;

  function update(dt) {
    // move player
    if (keys.ArrowUp) player.y -= player.speed * dt;
    if (keys.ArrowDown) player.y += player.speed * dt;
    if (keys.ArrowLeft) player.x -= player.speed * dt;
    if (keys.ArrowRight) player.x += player.speed * dt;
    // keep inside canvas
    player.x = Math.max(player.r, Math.min(w - player.r, player.x));
    player.y = Math.max(player.r, Math.min(h - player.r, player.y));

    // spawn obstacles
    if (performance.now() - lastSpawn > spawnInterval) {
      const size = 20 + Math.random()*30;
      const x = Math.random()*w;
      const y = Math.random()*h;
      const angle = Math.random()*2*Math.PI;
      const speed = 50 + Math.random()*100;
      obstacles.push({x, y, w:size, h:size, vx:Math.cos(angle)*speed, vy:Math.sin(angle)*speed});
      lastSpawn = performance.now();
    }

    // move obstacles
    for (let i=obstacles.length-1;i>=0;i--) {
      const o = obstacles[i];
      o.x += o.vx*dt;
      o.y += o.vy*dt;
      // remove if out of bounds
      if (o.x < -o.w || o.x > w || o.y < -o.h || o.y > h) obstacles.splice(i,1);
    }

    // collision detection
    for (const o of obstacles) {
      const closestX = Math.max(o.x, Math.min(player.x, o.x+o.w));
      const closestY = Math.max(o.y, Math.min(player.y, o.y+o.h));
      const dx = player.x - closestX;
      const dy = player.y - closestY;
      if (dx*dx + dy*dy < player.r*player.r) {
        gameOver = true;
        break;
      }
    }
  }

  function draw() {
    ctx.clearRect(0,0,w,h);
    // player
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.r, 0, Math.PI*2);
    ctx.fill();
    // obstacles
    ctx.fillStyle = 'red';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }
    // score
    ctx.fillStyle = 'black';
    ctx.font = '16px sans-serif';
    const elapsed = ((performance.now() - startTime)/1000).toFixed(2);
    ctx.fillText(`Time: ${elapsed}s`, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0,0,w,h);
      ctx.fillStyle = 'white';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', w/2, h/2);
    }
  }

  function loop(ts) {
    if (!startTime) startTime = ts;
    const dt = (ts - (lastTime||ts))/1000;
    lastTime = ts;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  let lastTime;
  requestAnimationFrame(loop);
})();
